\begin{itemize}
  \item $n$ is an even positive integer, $[n] := \{1, \dots, n\}$, and all asymptotics are as $n \to \infty$.
  \item Variables are split into two blocks of $n$ each, written $x = (x_1, \dots, x_n)$ and $x' = (x'_1, \dots, x'_n)$.
  \item An algorithm $\mathcal{A}$ is \emph{efficient} if it is probabilistic and runs in time polynomial in the bit length of its input; polynomials are given to it by their coefficient vectors.
  \item A function $P : \mathbb{N} \to \mathbb{N}$ is \emph{polynomially bounded} if $P(n) \le n^{O(1)}$.
\end{itemize}
